// volatile: single writer (main thread), many readers
private volatile boolean shuttingDown = false;

// AtomicInteger: many threads increment
private AtomicInteger requestCount = new AtomicInteger(0);
void handleRequest() { requestCount.incrementAndGet(); }

// synchronized: compound multi-variable update
private synchronized void transfer(Account from, Account to, int amount) {
    from.debit(amount); to.credit(amount); // must be atomic together
}
